using System.Text.Json.Nodes;
namespace SmartTrainingPresenter;
public sealed partial class Trainer {
 JsonNode DefaultPreferences()=>new JsonObject{["sound"]=true,["visual"]=true,["autoStart"]=false,["volume"]=.6,["noticeSeconds"]=5,["soundSet"]=0,["barMode"]="مصغّر"};
 void ShowSettings(){using var f=new Form{Text="إعدادات الواجهة والمؤقت",ClientSize=new(680,650),StartPosition=FormStartPosition.CenterParent,RightToLeft=RightToLeft.Yes,Font=Font};var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new(20)};JsonNode pref=Project?.Node["preferences"]??(File.Exists(Path.Combine(BaseProfile,"DefaultPreferences.json"))?J.Load(Path.Combine(BaseProfile,"DefaultPreferences.json")):DefaultPreferences());void ChangedPreference(){if(Project!=null)Changed();else J.Atomic(Path.Combine(BaseProfile,"DefaultPreferences.json"),pref);}void Label(string text)=>flow.Controls.Add(new Label{Text=text,AutoSize=true,MaximumSize=new(620,0)});Label("المظهر");var theme=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=260,AccessibleName="الثيم"};theme.Items.AddRange(new object[]{"فاتح","داكن","رملي"});theme.SelectedIndex=ThemeIndex;theme.SelectedIndexChanged+=(_,_)=>{ApplyTheme(theme.SelectedIndex);J.Atomic(Path.Combine(Profile,"UIAppearance.json"),JsonValue.Create(theme.Text)!);ApplyPalette(f);};flow.Controls.Add(theme);Label("شريط المؤقت");var mode=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=260,AccessibleName="نمط المؤقت"};mode.Items.AddRange(new object[]{"مصغّر","ثابت","مخفي"});mode.SelectedItem=DockMode;mode.SelectedIndexChanged+=(_,_)=>{if(Project!=null)SetDockMode(mode.Text);};flow.Controls.Add(mode);foreach(var key in new[]{"sound","visual","autoStart"}){var k=key;var check=new CheckBox{Text=key=="sound"?"التنبيهات الصوتية":key=="visual"?"التنبيهات المرئية":"بدء تلقائي عند اختيار النشاط",AutoSize=true,Checked=J.Bool(pref,key)};check.CheckedChanged+=(_,_)=>{pref[k]=check.Checked;ChangedPreference();};flow.Controls.Add(check);}void Number(string key,string label,decimal min,decimal max){Label(label);var num=new NumericUpDown{Minimum=min,Maximum=max,DecimalPlaces=2,Value=(decimal)J.Num(pref,key),Width=110};num.ValueChanged+=(_,_)=>{pref[key]=(double)num.Value;ChangedPreference();};flow.Controls.Add(num);}Number("volume","مستوى الصوت",0,1);Number("noticeSeconds","مدة التنبيه المرئي (ثانية)",1,60);foreach(var threshold in new[]{300,60,0}){var t=threshold;flow.Controls.Add(Btn("اختبار الصوت "+t,()=>PlaySound(t),"طلب تشغيل محلي؛ السماع لا يثبته الإرسال البرمجي"));}Label("عارض PDF والاعتماديات");var engine=new Label{Text=Pdf.Description,AutoSize=true,MaximumSize=new(620,0)};flow.Controls.Add(engine);var probe=Btn("فحص عارض Windows PDF",()=>{},"فحص العارض المحلي دون مكتبة ودون اتصال سحابي");probe.Click+=async(_,_)=>{try{var count=await Pdf.Pages(Path.Combine(AppContext.BaseDirectory,"Resources","pdf-engine-probe.pdf"));engine.Text="جاهز — نجح فتح PDF صناعي، "+count+" صفحة";}catch(Exception e){engine.Text="تعذر تجهيز العارض: "+e.Message;}};flow.Controls.Add(probe);Label("يعتمد التطبيق على .NET Desktop Runtime 10 x64 وميزات PDF في Windows. لا يعتمد على cache بيئة Codex أو محول خارجي لعرض PDF.");Label("مكان البيانات الدائم: "+BaseProfile);flow.Controls.Add(Btn("حول التطبيق",About,"الإصدار والبناء من معلومات البناء"));flow.Controls.Add(Btn("تم",()=>f.Close(),"حفظ الإعدادات والعودة"));f.Controls.Add(flow);ApplyPalette(f);f.ShowDialog(this);}
 void ShowSharingSettings(){using var f=new Form{Text="وضع الشاشة وخيارات المشاركة",ClientSize=new(580,300),StartPosition=FormStartPosition.CenterParent,RightToLeft=RightToLeft.Yes,Font=Font};var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new(20)};flow.Controls.Add(new Label{Text=$"الشاشات الفعلية: {Screen.AllScreens.Length}",AutoSize=true});foreach(var c in new[]{showClock,overtime,mute}){var origin=c;var check=new CheckBox{Text=c.Text,Checked=c.Checked,AutoSize=true};check.CheckedChanged+=(_,_)=>{origin.Checked=check.Checked;SavePreferences();};flow.Controls.Add(check);}flow.Controls.Add(Btn("نقل الجمهور للشاشة التالية",MoveAudience,"استخدام الشاشات الفعلية فقط"));flow.Controls.Add(Btn("تم",()=>f.Close(),"إغلاق الخيارات"));f.Controls.Add(flow);ApplyPalette(f);f.ShowDialog(this);}
}
